SELECT h.homeworkid, h.title, h.content, h.courseid, h.teacherid, h.type, h.deadline, h.createtime, h.attachment, c.coursename, c.semester, t.teachername, (SELECT COUNT(*) FROM studenthomework sh WHERE sh.homeworkid = h.homeworkid AND sh.status > 0) as submitcount FROM homework h LEFT JOIN course c ON h.courseid = c.courseid LEFT JOIN teacher t ON h.teacherid = t.teacherid
AND h.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY h.createtime DESC LIMIT #{offset}, #{limit}

SELECT h.homeworkid, h.title, h.content, h.courseid, h.teacherid, h.type, h.deadline, h.createtime, h.attachment, c.coursename, c.semester, t.teachername, (SELECT COUNT(*) FROM studenthomework sh WHERE sh.homeworkid = h.homeworkid AND sh.status > 0) as submitcount, (SELECT GROUP_CONCAT(ci.classname SEPARATOR ',') FROM courseclass cc LEFT JOIN classinfo ci ON cc.classid = ci.classid WHERE cc.courseid = h.courseid) as classNamesStr FROM homework h LEFT JOIN course c ON h.courseid = c.courseid LEFT JOIN teacher t ON h.teacherid = t.teacherid
INNER JOIN courseclass cc ON h.courseid = cc.courseid AND cc.classid = #{classid}
WHERE h.teacherid = #{teacherid}
AND h.title LIKE CONCAT('%', #{keyword}, '%')
AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))
AND c.semester = #{semester}
ORDER BY h.createtime DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM homework h
LEFT JOIN course c ON h.courseid = c.courseid

  INNER JOIN courseclass cc ON h.courseid = cc.courseid AND cc.classid = #{classid}

WHERE h.teacherid = #{teacherid}

    AND h.title LIKE CONCAT('%', #{keyword}, '%')




            AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))


            AND c.semester = #{semester}

SELECT DISTINCT h.homeworkid, h.title, h.content, h.courseid, h.teacherid, h.type, h.deadline, h.createtime, h.attachment, c.coursename, c.semester, t.teachername FROM homework h LEFT JOIN course c ON h.courseid = c.courseid LEFT JOIN teacher t ON h.teacherid = t.teacherid INNER JOIN courseclass cc ON h.courseid = cc.courseid WHERE cc.classid = #{classid}
AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))
AND c.semester = #{semester}
ORDER BY h.createtime DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT h.homeworkid) FROM homework h LEFT JOIN course c ON h.courseid = c.courseid INNER JOIN courseclass cc ON h.courseid = cc.courseid WHERE cc.classid = #{classid}
AND (c.semester = #{semester} OR c.semester LIKE CONCAT(#{semester}, '-%'))
AND c.semester = #{semester}

